service.method:

        INSERT INTO SFORM_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, FORM_ID
			, FORM_JSON
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${session.HOUSE_CODE}
			, ${FORM_ID}
			, ${FORM_JSON}
			, ${session.id}
			, ${current.DATE}
			, ${current.TIME}
		)


INSERT INTO SFORM
( 
	  HOUSE_CODE
	, FORM_ID
	, FORM_JSON
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  '000'
	, ${FORM_ID}
	, ${FORM_JSON}
	, ${session.ID}
	, ${current.date}
	, ${current.time}
	, ${session.ID}
	, ${current.date}
	, ${current.time}
	, 'N'
)


UPDATE
	SFORM 
SET
	  FORM_JSON 		= ${FORM_JSON}         
	, CHANGE_USER_ID 	= ${session.ID}        
	, CHANGE_DATE 		= ${current.date}      
	, CHANGE_TIME 		= ${current.time}      
WHERE
	HOUSE_CODE 	= '000'
AND FORM_ID 	= ${FORM_ID}


SELECT
	COUNT(*)
FROM
	SLANG 
WHERE
	SCREEN_ID 	= ${FORM_ID}
AND LANGUAGE 	= ${session.LANGUAGE}
AND CODE 		= ${CODE}
AND HOUSE_CODE 	= '000'


UPDATE
	SLANG 
SET
	  CONTENTS    		= ${CONTENTS}
	, CHANGE_USER_ID 	= ${session.ID}
	, CHANGE_DATE 		= ${current.DATE}
	, CHANGE_TIME 		= ${current.TIME}
WHERE
	SCREEN_ID 	= ${FORM_ID}
AND CODE 		= ${CODE}
AND HOUSE_CODE 	= '000'
AND LANGUAGE 	= ${session.LANGUAGE}


INSERT INTO SLANG
(
	  HOUSE_CODE
	, SCREEN_ID
	, LANGUAGE
	, CODE
	, CONTENTS
	, ADD_USER_ID
	, ADD_DATE
	, ADD_TIME
	, CHANGE_USER_ID
	, CHANGE_DATE
	, CHANGE_TIME
	, DEL_FLAG
)
VALUES
(
	  '000'
	, ${FORM_ID}
	, ${session.LANGUAGE}
	, ${CODE}
	, ${CONTENTS}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, ${session.ID}
	, ${current.DATE}
	, ${current.TIME}
	, 'N'
)


        INSERT INTO SLANG_HISTORY
		(
			  HISTORY_KEY
			, ACTION_MODE
			, HOUSE_CODE
			, SCREEN_ID
			, LANGUAGE
			, CODE
			, CONTENTS
			, ADD_USER_ID
			, ADD_DATE
			, ADD_TIME
		)
		VALUES
		(
			  ${HISTORY_KEY}
			, ${ACTION_MODE}
			, ${session.HOUSE_CODE}
			, ${FORM_ID}
			, ${LANGUAGE}
			, ${CODE}
			, ${CONTENTS}
			, ${session.ID}
			, ${current.DATE}
			, ${current.TIME}
		)
